import 'dart:convert';import 'dart:io';import 'package:file_picker/file_picker.dart';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:share_plus/share_plus.dart';import 'package:path_provider/path_provider.dart';import '../core/contrast.dart';import '../data/backup_service.dart';import '../domain/task.dart';import 'providers.dart';
class SettingsSheet extends ConsumerWidget{final List<Task> tasks;const SettingsSheet({required this.tasks,Key? key}):super(key:key);static const themes={'آبی':0xff1769aa,'سبز':0xff176b3a,'بنفش':0xff623a92,'نارنجی':0xff8a3b00,'قرمز':0xffa31520,'فیروزه‌ای':0xff00645f,'قهوه‌ای':0xff654321};Future<String?> password(BuildContext c)async{final x=TextEditingController();return showDialog<String>(context:c,builder:(d)=>AlertDialog(title:const Text('گذرواژه پشتیبان'),content:TextField(controller:x,obscureText:true,decoration:const InputDecoration(labelText:'حداقل ۸ نویسه')),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(d,x.text),child:const Text('ادامه'))]));}
 @override Widget build(BuildContext context,WidgetRef ref)=>SafeArea(child:ListView(padding:const EdgeInsets.all(16),shrinkWrap:true,children:[const Text('تنظیمات و پشتیبان',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:12),Wrap(spacing:8,children:themes.entries.map((e){final color=Color(e.value);return ChoiceChip(label:Text(e.key,style:TextStyle(color:readableOn(color))),backgroundColor:color,selected:ref.watch(themeSeedProvider)==e.value,onSelected:(_)=>ref.read(themeSeedProvider.notifier).state=e.value);}).toList()),DropdownButtonFormField<String>(value:ref.watch(darkModeProvider),decoration:const InputDecoration(labelText:'حالت نمایش'),items:['خودکار','روشن','تیره'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>ref.read(darkModeProvider.notifier).state=x!),DropdownButtonFormField<int>(value:ref.watch(occasionReminderDaysProvider),decoration:const InputDecoration(labelText:'یادآوری مناسبت، چند روز زودتر'),items:List.generate(8,(i)=>DropdownMenuItem(value:i,child:Text('$i روز'))),onChanged:(x)=>ref.read(occasionReminderDaysProvider.notifier).state=x!),ListTile(title:const Text('ساخت پشتیبان رمزگذاری‌شدهٔ .bvb'),onTap:()async{final pass=await password(context);if(pass==null||pass.length<8)return;final bytes=await BackupService().encrypt(jsonEncode(tasks.map((t)=>t.toJson()).toList()),pass);final dir=await getTemporaryDirectory();final f=File('${dir.path}/barnamevar_backup.bvb');await f.writeAsBytes(bytes);await Share.shareXFiles([XFile(f.path)],text:'پشتیبان برنامه‌ور');}),ListTile(title:const Text('بازیابی پشتیبان .bvb'),onTap:()async{final pick=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['bvb'],withData:true);if(pick==null)return;final pass=await password(context);if(pass==null)return;try{final json=await BackupService().decrypt(pick.files.single.bytes!,pass);final decoded=(jsonDecode(json) as List).map((x)=>Task.fromJson(Map<String,dynamic>.from(x))).toList();await ref.read(tasksProvider.notifier).replace(decoded);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('بازیابی انجام شد')));}catch(_){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('گذرواژه یا فایل نامعتبر است')));}})]));}
